/**
 * Playwright's `ElementState` (`injectedScript.ts`), every value, so the glue's `missingState`
 * result type-checks against Playwright's own union.
 */
export type ElementState =
  | 'visible'
  | 'hidden'
  | 'enabled'
  | 'disabled'
  | 'editable'
  | 'checked'
  | 'unchecked'
  | 'indeterminate'
  | 'stable'
  | 'non-inert'

/** The element was detached from its document, or its document was replaced. */
export type NotConnected = 'error:notconnected'

/** What `checkElementStates` reports when the element is not ready. */
export type ElementStatesOutcome = NotConnected | MissingState

/** The first state that does not hold, in Playwright's order, with `stable` first. */
export type MissingState = {
  missingState: ElementState
}

/**
 * The `block` and `inline` of `scrollIntoView`; Playwright cycles through `end`, `center` and
 * `start`.
 */
export type ScrollAlignment = 'start' | 'center' | 'end' | 'nearest'

/**
 * The input a hit-target interceptor judges, as `InjectedScript.setupHitTargetInterceptor` takes
 * it: `hover` judges `mousemove`, `tap` the pointer and touch events, `mouse` the presses and
 * clicks, and `drag` arms nothing.
 */
export type HitTargetAction = 'hover' | 'tap' | 'mouse' | 'drag'

/** What `stop()` reports. */
export type HitTargetOutcome = HitTargetDone | HitTargetBlocked

/** The first trusted mouse event hit the element, or no event arrived. */
export type HitTargetDone = 'done'

/**
 * The first trusted mouse event hit another element. The interceptor blocked it and every later
 * event of the action.
 */
export type HitTargetBlocked = {
  hitTargetDescription: string
}

/** The first selector match's visibility and preview, with the total match count for the log. */
export type SelectorMatch = {
  count: number
  visible: boolean
  preview: string
}

/**
 * The states `frames.ts` `_elementState` reads, one per `Frame.is*` command that waits for a
 * match.
 */
export type ReadableElementState = 'checked' | 'enabled' | 'disabled' | 'editable'

/** The first match's `ElementStateQueryResult` for one state, and its preview. */
export type ElementStateMatch = {
  /** Whether the element is in the state asked for. */
  matches: boolean
  /** `error:notconnected` ends the call as Playwright's `throwElementIsNotAttached` does. */
  received?: string
  preview: string
}

/** The first matching element's text. */
export type TextMatch = {
  /** `textContent` or `innerText` of the element, never `null` for an element. */
  value: string
  /**
   * `InjectedScript.previewNode` of the element, for the call log line
   * `locator resolved to …`.
   */
  preview: string
}

/** The first matching element's attribute and preview. */
export type AttributeMatch = {
  /** `element.getAttribute(name)`: absent when the element has no such attribute, '' when empty. */
  value?: string
  preview: string
}

/** The snapshot flavor: `ai` adds refs that `aria-ref=` selectors resolve. */
export type AriaSnapshotMode = 'ai' | 'default'

/** One document's tree, before neo-runtime stitches in its iframes. */
export type AriaFrameSnapshot = {
  /** Playwright's `AriaSnapshotJSON`, unchanged. */
  nodes: AriaNode[]
  /**
   * The rendered `iframe` nodes in document order, with their depth in this tree. The glue
   * joins Playwright's `iframeRefs` list and `iframeDepths` record into this list.
   */
  iframes: AriaIframe[]
}

/** An `iframe` node of a snapshot. */
export type AriaIframe = {
  /** The node's `ref`, which an `aria-ref=` selector names. */
  ref: string
  /** The node's depth in its document's tree. */
  depth: number
}

/**
 * Playwright's `AriaNodeJSON` (`packages/isomorphic/ariaSnapshot.ts`), field for field. Its
 * literal `true` flags widen to `boolean`, which the glue's `satisfies` check accepts.
 */
export type AriaNode = {
  role: AriaRole
  name?: string
  checked?: AriaTristate
  disabled?: boolean
  expanded?: boolean
  active?: boolean
  invalid?: AriaInvalid
  level?: number
  pressed?: AriaTristate
  selected?: boolean
  ariaHidden?: boolean
  ref?: string
  cursor?: 'pointer'
  box?: AriaBox
  url?: string
  placeholder?: string
  text?: string
  children?: AriaChild[]
}

/**
 * The element's client rect, which Playwright rounds to whole pixels. Decoding these as integers
 * relies on CDP writing an integral double as a JSON integer, `-0` included: serde rejects a
 * literal `-0` for an integer.
 */
export type AriaBox = {
  x: number
  y: number
  width: number
  height: number
}

/** A child of an aria node: another node, or a run of text. */
export type AriaChild = AriaNode | string

/** A checked or pressed state. Playwright sends only `true` or `'mixed'`. */
export type AriaTristate = boolean | 'mixed'

/** An invalid state. Playwright sends only `true`, `'grammar'` or `'spelling'`. */
export type AriaInvalid = boolean | 'grammar' | 'spelling'

/** Playwright's `AriaRole`, plus `iframe` and `text`. */
